async function getPlayerUnlockState(playerId) {
  const player = await getGamePlayerById(playerId);
  if (!player) return null;
  const levels = player.levelsData || [];
  const level1Done = levels.some((l2) => l2.id === 1 && l2.completed);
  const level2Done = levels.some((l2) => l2.id === 2 && l2.completed);
  const level3Done = levels.some((l2) => l2.id === 3 && l2.completed);
  const has500XP = player.xp >= 500;
  return {
    xp: player.xp,
    currentLevel: player.currentLevel,
    levelsData: levels,
    unlocks: {
      jugar: true,
      creaTuLincelin: true,
      personajes: true,
      perfil: true,
      recompensas: true,
      arsenalIA: level1Done,
      promptStudio: level1Done,
      promptear: level1Done,
      mundo: level2Done,
      raids: level3Done,
      academia: has500XP
    }
  };
}
